import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, calculateDueDate } from './dates.js';

/**
 * Validate a discount percent value (0-100, can be decimal).
 * @param {unknown} discountPercent
 * @returns {boolean}
 */
function isValidDiscountPercent(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Calculate the total for a single line: qty times unitPrice.
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number} total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line: lineTotal times discountPercent / 100.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
 * @returns {number} discount in cents, clamped to >= 0
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const total = lineTotal(line);
  const discount = roundCents(total * discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate the VAT for a single line: (lineTotal - lineDiscount) times vatRate / 100.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }}
 * @returns {number} VAT in cents, clamped to >= 0
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const netTotal = total - discount;
  const vat = roundCents(netTotal * line.vatRate / 100);
  return Math.max(0, vat);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { amount: number } }}
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} all in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms?: string, dueDate?: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate date format and validity
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate terms if provided
  const effectiveTerms = terms ?? 'NET30';
  if (!['NET14', 'NET30', 'EOM'].includes(effectiveTerms)) {
    return fail('TERMS_INVALID');
  }

  // Calculate due date
  const dueDate = calculateDueDate(issueDate, effectiveTerms);

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Process and validate each line
  const processedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discount percent if provided
    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product from catalogue
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const processedLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Apply discount: line's own discountPercent wins, otherwise use tier discount
    if (line.discountPercent !== undefined) {
      processedLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier];
      if (tierDiscount > 0) {
        processedLine.discountPercent = tierDiscount;
      }
    }

    processedLines.push(processedLine);
  }

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: processedLines,
    terms: effectiveTerms,
    dueDate,
  };

  return ok(invoice);
}

/**
 * Add or update a line on an invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} param1
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discount percent if provided
  if (discountPercent !== undefined && !isValidDiscountPercent(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  // Get product from catalogue to validate SKU exists
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Create new lines array with either updated or added line
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  let newLines;

  if (existingLineIndex >= 0) {
    // Update existing line: increase qty, keep or replace discount
    newLines = invoice.lines.map((line, idx) => {
      if (idx === existingLineIndex) {
        const updated = { ...line, qty: line.qty + qty };
        if (discountPercent !== undefined) {
          updated.discountPercent = discountPercent;
        }
        return updated;
      }
      return line;
    });
  } else {
    // Add new line at the end
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }

    newLines = [...invoice.lines, newLine];
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check line exists
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check there's more than one line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without the line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and setting status to 'issued'.
 * @param {{ status: string }} invoice
 * @param {string[]} existingNumbers array of invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: object }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check no voucher already applied
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  // Validate amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

